{
  "project_id": "e090a49792924ce6b0bb",
  "name": "user-stats",
  "entrypoint_path": "index.ts",
  "import_map_path": "deno.json",
  "verify_jwt": false,
  "files": [
    {
      "name": "index.ts",
      "content": "import { withSupabase } from "npm:@supabase/server";

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export default {
  fetch: withSupabase({ auth: ["user", "secret"] }, async (req, ctx) => {
    if (req.method !== "GET" && req.method !== "POST") {
      return Response.json({ error: "Method not allowed" }, {
        status: 405,
        headers: { Allow: "GET, POST" },
      });
    }

    let query;

    if (ctx.authMode === "user") {
      // Deliberately ignore any supplied user_id: user clients can only read as themselves.
      const userId = ctx.userClaims?.id;
      if (typeof userId !== "string") {
        return Response.json({ error: "Unauthorized" }, { status: 401 });
      }

      // This client carries the caller's JWT, so the table's RLS policy is enforced too.
      query = ctx.supabase.from("user_stats").select("*").eq("user_id", userId);
    } else {
      let body: unknown;
      try {
        body = await req.json();
      } catch {
        return Response.json({ error: "A JSON body with user_id is required" }, { status: 400 });
      }

      const userId =
        typeof body === "object" && body !== null && "user_id" in body
          ? (body as { user_id?: unknown }).user_id
          : undefined;

      if (typeof userId !== "string" || !UUID_RE.test(userId)) {
        return Response.json({ error: "user_id must be a valid UUID" }, { status: 400 });
      }

      // Only a validated secret-key caller reaches this branch.
      query = ctx.supabaseAdmin.from("user_stats").select("*").eq("user_id", userId);
    }

    const { data, error } = await query;
    if (error) {
      console.error("Unable to load user stats", { code: error.code, message: error.message });
      return Response.json({ error: "Unable to load user stats" }, { status: 500 });
    }

    return Response.json(data);
  }),
};
"
    },
    {
      "name": "deno.json",
      "content": "{
  "compilerOptions": {
    "strict": true
  }
}
"
    }
  ]
}

